<script setup>
import { computed, onMounted, ref } from 'vue'
import { api, demoProjects, demoQuotes, demoTemplates, demoUsers, getCurrentUserId, setCurrentUserId } from './services/api'

const API_URL = import.meta.env.VITE_API_URL || '/api'
const page = ref('dashboard')
const projects = ref([])
const quotes = ref([])
const templates = ref([])
const users = ref([])
const files = ref([])
const currentFolder = ref('')
const apiOffline = ref(false)
const search = ref('')
const toast = ref('')
const summary = ref({ projects: 2, activeQuotes: 1, documents: 24, teamMembers: 2 })
const showProjectModal = ref(false)
const showProjectDetails = ref(false)
const showQuoteModal = ref(false)
const showTemplateModal = ref(false)
const editingProject = ref(null)
const editingQuote = ref(null)
const editingTemplate = ref(null)
const projectDetails = ref(null)
const projectActivity = ref([])
const currentUserId = ref(Number(getCurrentUserId()))
const projectForm = ref({ projectNumber: '', name: '', contactPerson: '', description: '', status: 'ACTIVE' })
const templateForm = ref({ name: '', description: '', language: 'CPP', content: '' })
const quoteForm = ref({ projectId: null, templateId: null, name: '', description: '', status: 'DRAFT', steps: [] })
const templateTokens = '{{TEST_CLASS}}, {{STEPS}}'
const templateTokensFull = '{{QUOTE_ID}}, {{QUOTE_NAME}}, {{PROJECT_NUMBER}}, {{PROJECT_NAME}}, {{TEST_CLASS}}, {{STEPS}}'

const activeUser = computed(() => users.value.find(user => Number(user.id) === Number(currentUserId.value)) ||
  { displayName: 'Alex Martin', role: 'ADMIN' })

const projectQuotes = computed(() => {
  if (!projectDetails.value) return []
  return quotes.value.filter(quote => quote.projectId === projectDetails.value.id ||
    (!quote.projectId && quote.projectNumber === projectDetails.value.projectNumber))
})

const navItems = [
  { id: 'dashboard', label: 'Vue d’ensemble', icon: '⌂' },
  { id: 'projects', label: 'Projets', icon: '▦' },
  { id: 'quotes', label: 'Devis de tests', icon: '✓' },
  { id: 'templates', label: 'Templates C++', icon: 'T' },
  { id: 'documents', label: 'Documentation', icon: '▤' },
]

const filteredProjects = computed(() => projects.value.filter(project =>
  `${project.projectNumber} ${project.name} ${project.contactPerson || ''}`.toLowerCase().includes(search.value.toLowerCase())))

function emptyStep(stepNumber = 1) {
  return { stepNumber, subStep: 1, startCondition: '', pinToTest: '', measurementType: 'VOLTAGE', unit: 'V', expectedMin: null, expectedMax: null, relay: '', voltage: null, notes: '' }
}

function defaultTemplateContent() {
  return '// Generated by MegaFinder - Test quote #{{QUOTE_ID}}\n#include <gtest/gtest.h>\n\nclass {{TEST_CLASS}} : public ::testing::Test {};\n\n{{STEPS}}'
}

async function loadData() {
  try {
    const [projectData, quoteData, userData, summaryData, templateData] = await Promise.all([
      api('/projects'), api('/test-quotes'), api('/users'), api('/dashboard/summary'), api('/test-templates'),
    ])
    projects.value = projectData; quotes.value = quoteData; users.value = userData; templates.value = templateData; summary.value = summaryData; apiOffline.value = false
    await loadFiles()
  } catch {
    apiOffline.value = true; projects.value = demoProjects; quotes.value = demoQuotes; templates.value = demoTemplates; users.value = demoUsers
  }
}

async function loadFiles(folder = currentFolder.value) {
  currentFolder.value = folder
  try { files.value = (await api(`/files?path=${encodeURIComponent(folder)}`)).items } catch { files.value = demoFiles(folder) }
}

function demoFiles(folder) {
  if (folder) return [{ name: 'README.md', type: 'file', extension: 'md', path: `${folder}/README.md`, openUri: '' }]
  return [{ name: 'projets', type: 'directory', extension: '', path: 'projets', openUri: '' }, { name: 'README.md', type: 'file', extension: 'md', path: 'README.md', openUri: '' }]
}

function fileSystemPath(file) {
  const uri = file.openUri || ''
  const rawPath = uri.startsWith('file:///') ? uri.slice('file:///'.length) : uri
  const path = decodeURIComponent(rawPath)
  return /^[A-Za-z]:\//.test(path) ? path.replaceAll('/', '\\') : path
}

function openFile(file) {
  if (file.type === 'directory') return loadFiles(file.path)
  if (file.openUri) window.open(file.openUri, '_blank', 'noopener,noreferrer')
  else copyFilePath(file)
}

async function copyFilePath(file) {
  const path = fileSystemPath(file)
  try { await navigator.clipboard.writeText(path); notify('Chemin local copié') } catch { notify(`Chemin local : ${path}`) }
}

function openProjectModal(project = null) {
  editingProject.value = project
  projectForm.value = project ? { ...project } : { projectNumber: '', name: '', contactPerson: '', description: '', status: 'ACTIVE' }
  showProjectModal.value = true
}

async function openProjectDetails(project) {
  projectDetails.value = project
  projectActivity.value = []
  page.value = 'project-detail'
  if (apiOffline.value) {
    projectActivity.value = [{ action: 'UPDATED', details: 'Dernière information disponible dans la maquette.', actorName: 'Alex Martin', createdAt: project.updatedAt }]
    await loadFiles(project.documentationPath)
    return
  }
  try {
    const [details, activity] = await Promise.all([api(`/projects/${project.id}`), api(`/projects/${project.id}/activity`)]);
    projectDetails.value = details
    projectActivity.value = activity
    await loadFiles(details.documentationPath)
  } catch { notify('Impossible de charger les détails du projet'); await loadFiles(project.documentationPath) }
}

function backToProjects() { page.value = 'projects' }

function switchUser() {
  setCurrentUserId(currentUserId.value)
  notify(`Utilisateur actif : ${activeUser.value.displayName}`)
}

function formatDate(value) {
  if (!value) return '—'
  return new Intl.DateTimeFormat('fr-CA', { dateStyle: 'medium', timeStyle: 'short' }).format(new Date(value))
}

function activityLabel(action) {
  return ({ CREATED: 'Projet créé', UPDATED: 'Projet modifié' })[action] || action
}

async function saveProject() {
  try {
    if (apiOffline.value) {
      if (editingProject.value) Object.assign(editingProject.value, projectForm.value)
      else projects.value.unshift({ ...projectForm.value, id: Date.now(), documentationPath: `projets/${projectForm.value.projectNumber}` })
    } else await api(editingProject.value ? `/projects/${editingProject.value.id}` : '/projects', { method: editingProject.value ? 'PUT' : 'POST', body: JSON.stringify(projectForm.value) })
    showProjectModal.value = false; await loadData(); notify('Projet enregistré')
  } catch { notify('Impossible d’enregistrer le projet') }
}

async function deleteProject(project) {
  if (!confirm(`Supprimer ${project.projectNumber} ?`)) return
  if (!apiOffline.value) await api(`/projects/${project.id}`, { method: 'DELETE' })
  projects.value = projects.value.filter(item => item.id !== project.id); notify('Projet supprimé')
}

function openProjectDocuments(project) { page.value = 'documents'; loadFiles(project.documentationPath) }

async function openQuoteModal(quote = null, project = null) {
  editingQuote.value = quote
  if (quote && !apiOffline.value) {
    const detail = await api(`/test-quotes/${quote.id}`)
    quoteForm.value = { projectId: detail.projectId, templateId: detail.templateId, name: detail.name, description: detail.description || '', status: detail.status, steps: detail.steps || [] }
  } else quoteForm.value = { projectId: project?.id || projectDetails.value?.id || projects.value[0]?.id || null, templateId: templates.value[0]?.id || null, name: '', description: '', status: 'DRAFT', steps: [emptyStep()] }
  showQuoteModal.value = true
}

function addQuoteStep() { quoteForm.value.steps.push(emptyStep(quoteForm.value.steps.length + 1)) }

async function saveQuote() {
  try {
    if (apiOffline.value) {
      const project = projects.value.find(item => item.id === quoteForm.value.projectId)
      const localQuote = { id: editingQuote.value?.id || Date.now(), ...quoteForm.value, projectNumber: project?.projectNumber || 'MF-2401', projectName: project?.name || 'Projet démo', templateName: templates.value.find(item => item.id === quoteForm.value.templateId)?.name || 'GoogleTest standard', stepCount: quoteForm.value.steps.length }
      if (editingQuote.value) Object.assign(editingQuote.value, localQuote); else quotes.value.unshift(localQuote)
    } else await api(editingQuote.value ? `/test-quotes/${editingQuote.value.id}` : '/test-quotes', { method: editingQuote.value ? 'PUT' : 'POST', body: JSON.stringify(quoteForm.value) })
    showQuoteModal.value = false; await loadData(); notify('Devis enregistré')
  } catch { notify('Impossible d’enregistrer le devis') }
}

async function generateCpp(quote) {
  if (apiOffline.value) return notify('Mode présentation : génération C++ simulée')
  const response = await fetch(`${API_URL}/test-quotes/${quote.id}/generate-cpp`, { method: 'POST' }); const blob = await response.blob(); const url = URL.createObjectURL(blob)
  const anchor = document.createElement('a'); anchor.href = url; anchor.download = `test_quote_${quote.id}.cpp`; anchor.click(); URL.revokeObjectURL(url); notify('Fichier C++ généré')
}

function openTemplateModal(template = null) {
  editingTemplate.value = template
  templateForm.value = template ? { name: template.name, description: template.description || '', language: template.language || 'CPP', content: template.content } : { name: '', description: '', language: 'CPP', content: defaultTemplateContent() }
  showTemplateModal.value = true
}

async function saveTemplate() {
  try {
    if (apiOffline.value) {
      const localTemplate = { id: editingTemplate.value?.id || Date.now(), templateKey: 'CUSTOM', ...templateForm.value, system: false }
      if (editingTemplate.value) Object.assign(editingTemplate.value, localTemplate); else templates.value.push(localTemplate)
    } else await api(editingTemplate.value ? `/test-templates/${editingTemplate.value.id}` : '/test-templates', { method: editingTemplate.value ? 'PUT' : 'POST', body: JSON.stringify(templateForm.value) })
    showTemplateModal.value = false; await loadData(); notify('Template enregistré')
  } catch { notify('Impossible d’enregistrer le template') }
}

async function deleteTemplate(template) {
  if (template.system || !confirm(`Supprimer ${template.name} ?`)) return
  if (!apiOffline.value) await api(`/test-templates/${template.id}`, { method: 'DELETE' })
  templates.value = templates.value.filter(item => item.id !== template.id); notify('Template supprimé')
}

function notify(message) { toast.value = message; setTimeout(() => { toast.value = '' }, 2800) }
function statusLabel(status) { return ({ ACTIVE: 'Actif', ARCHIVED: 'Archivé', IN_PROGRESS: 'En cours', DRAFT: 'Brouillon' })[status] || status }
function goTo(id) { page.value = id; if (id === 'documents') loadFiles('') }
onMounted(loadData)
</script>

<template>
  <div class="app-shell">
    <aside class="sidebar"><div class="brand"><div class="brand-mark">M</div><div><strong>MegaFinder</strong><small>LAB OPERATIONS</small></div></div><div class="workspace-label">ESPACE DE TRAVAIL</div><nav><button v-for="item in navItems" :key="item.id" :class="{ active: page === item.id }" @click="goTo(item.id)"><span class="nav-icon">{{ item.icon }}</span>{{ item.label }}</button></nav><div class="sidebar-bottom"><button class="team-link" :class="{ active: page === 'team' }" @click="page = 'team'"><span class="nav-icon">◎</span>Équipe & accès</button><div class="user-card"><div class="avatar">{{ activeUser.displayName.split(' ').map(part => part[0]).join('').slice(0, 2) }}</div><div><strong>{{ activeUser.displayName }}</strong><small>{{ activeUser.role }}</small></div></div></div></aside>
    <main class="main-content">
      <header class="topbar"><div class="breadcrumbs"><span>MegaFinder</span><b>/</b><strong>{{ navItems.find(item => item.id === page)?.label || (page === 'project-detail' ? 'Détail du projet' : 'Équipe & accès') }}</strong></div><div class="top-actions"><span class="status-dot"></span><span class="sync-label">{{ apiOffline ? 'Mode démo' : 'Synchronisé' }}</span><select class="user-switcher" v-model="currentUserId" @change="switchUser"><option v-for="user in users" :key="user.id" :value="Number(user.id)">{{ user.displayName }}</option></select></div></header>
      <div v-if="apiOffline" class="demo-banner">Mode présentation actif — les données affichées sont une maquette locale.</div>
      <section v-if="page === 'dashboard'" class="page"><div class="page-heading"><div><p class="eyebrow">PILOTAGE</p><h1>Bonjour {{ activeUser.displayName.split(' ')[0] }}</h1><p class="subtitle">Voici l’état de vos opérations de test aujourd’hui.</p></div><button class="primary-button" @click="openProjectModal()">＋ Nouveau projet</button></div><div class="metric-grid"><div class="metric-card"><strong>{{ summary.projects }}</strong><span>Projets actifs</span></div><div class="metric-card"><strong>{{ summary.activeQuotes }}</strong><span>Devis en cours</span></div><div class="metric-card"><strong>{{ summary.documents }}</strong><span>Documents suivis</span></div><div class="metric-card"><strong>{{ summary.teamMembers }}</strong><span>Membres de l’équipe</span></div></div></section>
      <section v-else-if="page === 'projects'" class="page"><div class="page-heading"><div><p class="eyebrow">PILOTAGE</p><h1>Projets</h1><p class="subtitle">Cliquez sur un projet pour voir son historique.</p></div><button class="primary-button" @click="openProjectModal()">＋ Nouveau projet</button></div><div class="toolbar"><div class="search-box">⌕<input v-model="search" placeholder="Rechercher un projet..." /></div><span class="result-count">{{ filteredProjects.length }} projets</span></div><div class="panel table-panel"><table><thead><tr><th>PROJET</th><th>CONTACT</th><th>DOSSIER</th><th>STATUT</th><th></th></tr></thead><tbody><tr v-for="project in filteredProjects" :key="project.id"><td><button class="project-link" @click="openProjectDetails(project)"><span class="project-avatar">{{ project.projectNumber.slice(-2) }}</span><span><strong>{{ project.name }}</strong><small>{{ project.projectNumber }}</small></span></button></td><td>{{ project.contactPerson || '—' }}</td><td class="description-cell">{{ project.documentationPath }}</td><td><span class="badge" :class="project.status.toLowerCase()">{{ statusLabel(project.status) }}</span></td><td class="actions"><button @click="openProjectDetails(project)">Détails</button><button @click="openProjectDocuments(project)">Docs</button><button @click="openProjectModal(project)">Modifier</button><button class="danger-link" @click="deleteProject(project)">Supprimer</button></td></tr></tbody></table></div></section>
      <section v-else-if="page === 'project-detail' && projectDetails" class="page project-detail-page"><div class="detail-page-heading"><button class="back-button" @click="backToProjects">← Projets</button><div class="detail-heading-actions"><button class="filter-button" @click="openProjectModal(projectDetails)">Modifier</button><button class="primary-button" @click="openProjectDocuments(projectDetails)">Ouvrir la documentation</button></div></div><div class="project-hero"><div><p class="eyebrow">FICHE PROJET</p><div class="project-title-line"><span class="project-avatar large">{{ projectDetails.projectNumber.slice(-2) }}</span><div><h1>{{ projectDetails.name }}</h1><span class="detail-project-number">{{ projectDetails.projectNumber }}</span></div></div><p class="subtitle">{{ projectDetails.description || 'Aucune description pour ce projet.' }}</p></div><span class="badge" :class="projectDetails.status.toLowerCase()">{{ statusLabel(projectDetails.status) }}</span></div><div class="project-detail-grid"><div class="project-main-column"><section class="panel detail-panel"><div class="panel-heading"><div><h2>Documentation</h2><p>{{ projectDetails.documentationPath }}</p></div><button class="text-button" @click="loadFiles(projectDetails.documentationPath)">Actualiser</button></div><div class="quick-files"><div v-for="file in files.slice(0, 5)" :key="file.path" class="quick-file" @click="file.type === 'directory' ? loadFiles(file.path) : openFile(file)"><div class="file-icon" :class="file.type">{{ file.type === 'directory' ? '▰' : '▤' }}</div><div><strong>{{ file.name }}</strong><small>{{ file.type === 'directory' ? 'Dossier' : file.extension.toUpperCase() + ' · fichier local' }}</small></div><span>→</span></div><div v-if="!files.length" class="empty-state compact-empty">Aucun fichier dans ce dossier.</div></div></section><section class="panel detail-panel"><div class="panel-heading"><div><h2>Devis de tests</h2><p>{{ projectQuotes.length }} devis liés à ce projet</p></div><button class="text-button" @click="openQuoteModal(null, projectDetails)">＋ Nouveau devis</button></div><div class="linked-quotes"><div v-for="quote in projectQuotes" :key="quote.id" class="linked-quote"><div><strong>{{ quote.name }}</strong><small>{{ quote.templateName || 'GoogleTest standard' }} · {{ quote.stepCount }} étapes</small></div><span class="badge" :class="quote.status.toLowerCase()">{{ statusLabel(quote.status) }}</span><div class="linked-quote-actions"><button class="filter-button compact-button" @click="openQuoteModal(quote)">Modifier</button><button class="outline-button compact-button" @click="generateCpp(quote)">Générer C++</button></div></div><div v-if="!projectQuotes.length" class="empty-state compact-empty">Aucun devis lié à ce projet.</div></div></section></div><aside class="project-side-column"><section class="panel detail-panel"><div class="panel-heading"><div><h2>Dernière activité</h2><p>{{ projectActivity.length }} événement{{ projectActivity.length > 1 ? 's' : '' }}</p></div></div><div class="activity-list"><div v-for="activity in projectActivity.slice(0, 5)" :key="activity.id || `${activity.action}-${activity.createdAt}`" class="project-activity"><div class="activity-mark">{{ activity.action === 'CREATED' ? '＋' : '↻' }}</div><div><strong>{{ activityLabel(activity.action) }}</strong><p>{{ activity.details }}</p><small>{{ activity.actorName || 'Utilisateur inconnu' }} · {{ formatDate(activity.createdAt) }}</small></div></div><div v-if="!projectActivity.length" class="empty-state compact-empty">Aucune activité disponible.</div></div></section><section class="panel detail-panel project-info"><h2>Informations</h2><dl><dt>Contact</dt><dd>{{ projectDetails.contactPerson || '—' }}</dd><dt>Dossier</dt><dd>{{ projectDetails.documentationPath }}</dd><dt>Dernière modification</dt><dd>{{ formatDate(projectDetails.updatedAt) }}</dd></dl></section></aside></div></section>
      <section v-else-if="page === 'quotes'" class="page"><div class="page-heading"><div><p class="eyebrow">AUTOMATISATION</p><h1>Devis de tests</h1><p class="subtitle">Chaque devis est lié à un projet et à un template C++.</p></div><button class="primary-button" @click="openQuoteModal()">＋ Nouveau devis</button></div><div class="quote-grid"><div v-for="quote in quotes" :key="quote.id" class="quote-card"><span class="badge" :class="quote.status.toLowerCase()">{{ statusLabel(quote.status) }}</span><h3>{{ quote.name }}</h3><p>{{ quote.projectNumber }} · {{ quote.projectName }}</p><small>Template : {{ quote.templateName || 'GoogleTest standard' }}</small><div class="quote-progress"><span><b>{{ quote.stepCount }}</b> étapes définies</span></div><div class="quote-card-actions"><button class="filter-button" @click="openQuoteModal(quote)">Modifier</button><button class="outline-button" @click="generateCpp(quote)">Générer C++</button></div></div><div class="quote-card new-card" @click="openQuoteModal()"><div class="new-plus">＋</div><strong>Créer un nouveau devis</strong><p>Choisir un projet et un template.</p></div></div></section>
      <section v-else-if="page === 'templates'" class="page"><div class="page-heading"><div><p class="eyebrow">GÉNÉRATION C++</p><h1>Templates de tests</h1><p class="subtitle">Modifiez le contenu utilisé pour générer les fichiers unitaires.</p></div><button class="primary-button" @click="openTemplateModal()">＋ Nouveau template</button></div><div class="template-grid"><div v-for="template in templates" :key="template.id" class="quote-card"><span class="badge active">{{ template.language }}</span><h3>{{ template.name }}</h3><p>{{ template.description || 'Aucune description' }}</p><small>Variables : {{ templateTokens }}</small><div class="quote-card-actions"><button class="filter-button" @click="openTemplateModal(template)">Modifier</button><button v-if="!template.system" class="danger-link" @click="deleteTemplate(template)">Supprimer</button></div></div></div></section>
      <section v-else-if="page === 'documents'" class="page"><div class="page-heading"><div><p class="eyebrow">ESPACE LOCAL</p><h1>Documentation</h1><p class="subtitle">Dossier courant : {{ currentFolder || 'racine' }}</p></div><button class="primary-button" @click="loadFiles()">↻ Actualiser</button></div><div class="path-bar"><b>/ documentation</b><span v-if="currentFolder">/ {{ currentFolder }}</span><button v-if="currentFolder" @click="loadFiles('')">Revenir à la racine</button></div><div class="panel files-panel"><div class="files-heading"><div><h2>Fichiers disponibles</h2><p>Le contenu reste sur votre disque local.</p></div><span>{{ files.length }} éléments</span></div><div v-for="file in files" :key="file.path" class="file-row" @dblclick="openFile(file)"><div class="file-icon" :class="file.type">{{ file.type === 'directory' ? '▰' : '▤' }}</div><div><strong>{{ file.name }}</strong><small>{{ file.type === 'directory' ? 'Dossier' : file.extension.toUpperCase() + ' · fichier local' }}</small></div><button v-if="file.type === 'directory'" @click="loadFiles(file.path)">Ouvrir →</button><div v-else class="file-actions"><button @click.stop="openFile(file)">Ouvrir ↗</button><button @click.stop="copyFilePath(file)">Copier le chemin</button></div></div><div v-if="!files.length" class="empty-state">Aucun fichier dans ce dossier.</div></div></section>
      <section v-else class="page"><div class="page-heading"><div><p class="eyebrow">ADMINISTRATION</p><h1>Équipe & accès</h1><p class="subtitle">Gérez les rôles et les droits complémentaires.</p></div></div><div class="panel table-panel"><table><thead><tr><th>MEMBRE</th><th>RÔLE</th><th>PERMISSIONS</th><th>STATUT</th></tr></thead><tbody><tr v-for="user in users" :key="user.id"><td><strong>{{ user.displayName }}</strong><small>{{ user.email }}</small></td><td>{{ user.role }}</td><td>{{ user.extraPermissions.join(', ') }}</td><td>Actif</td></tr></tbody></table></div></section>
    </main>
    <div v-if="showProjectModal" class="modal-backdrop" @click.self="showProjectModal = false"><div class="modal"><div class="modal-heading"><h2>{{ editingProject ? 'Modifier le projet' : 'Nouveau projet' }}</h2><button @click="showProjectModal = false">×</button></div><label>Numéro du projet<input v-model="projectForm.projectNumber" placeholder="MF-2402" /></label><label>Nom du projet<input v-model="projectForm.name" placeholder="Nom du projet" /></label><label>Personne à contacter<input v-model="projectForm.contactPerson" placeholder="Nom du contact" /></label><label>Description<textarea v-model="projectForm.description" rows="4"></textarea></label><div class="modal-actions"><button class="filter-button" @click="showProjectModal = false">Annuler</button><button class="primary-button" @click="saveProject">Enregistrer</button></div></div></div>
    <div v-if="showProjectDetails" class="modal-backdrop" @click.self="showProjectDetails = false"><div class="modal project-detail-modal"><div class="modal-heading"><div><p class="eyebrow">FICHE PROJET</p><h2>{{ projectDetails?.name }}</h2><span class="detail-project-number">{{ projectDetails?.projectNumber }}</span></div><button @click="showProjectDetails = false">×</button></div><div class="project-detail-summary"><div><span>Dernière modification</span><strong>{{ formatDate(projectDetails?.updatedAt) }}</strong></div><div><span>Dernière action</span><strong>{{ projectActivity.length ? activityLabel(projectActivity[0].action) : '—' }}</strong><small v-if="projectActivity.length">par {{ projectActivity[0].actorName || 'Utilisateur inconnu' }}</small></div></div><p class="detail-description">{{ projectDetails?.description || 'Aucune description.' }}</p><div class="activity-heading"><h3>Historique</h3><span>{{ projectActivity.length }} événement{{ projectActivity.length > 1 ? 's' : '' }}</span></div><div class="activity-list"><div v-for="activity in projectActivity" :key="activity.id || `${activity.action}-${activity.createdAt}`" class="project-activity"><div class="activity-mark">{{ activity.action === 'CREATED' ? '＋' : '↻' }}</div><div><strong>{{ activityLabel(activity.action) }}</strong><p>{{ activity.details }}</p><small>{{ activity.actorName || 'Utilisateur inconnu' }} · {{ formatDate(activity.createdAt) }}</small></div></div><div v-if="!projectActivity.length" class="empty-state">Aucun historique disponible.</div></div><div class="modal-actions"><button class="filter-button" @click="showProjectDetails = false">Fermer</button><button class="primary-button" @click="showProjectDetails = false; openProjectModal(projectDetails)">Modifier le projet</button></div></div></div>
    <div v-if="showQuoteModal" class="modal-backdrop" @click.self="showQuoteModal = false"><div class="modal quote-modal"><div class="modal-heading"><h2>{{ editingQuote ? 'Modifier le devis' : 'Nouveau devis' }}</h2><button @click="showQuoteModal = false">×</button></div><label>Projet<select v-model="quoteForm.projectId"><option v-for="project in projects" :key="project.id" :value="project.id">{{ project.projectNumber }} · {{ project.name }}</option></select></label><label>Template<select v-model="quoteForm.templateId"><option v-for="template in templates" :key="template.id" :value="template.id">{{ template.name }}</option></select></label><label>Nom du devis<input v-model="quoteForm.name" placeholder="Validation tension pin 2" /></label><label>Description<textarea v-model="quoteForm.description" rows="2"></textarea></label><div class="step-editor"><div class="step-editor-heading"><strong>Lignes de test</strong><button class="text-button" @click="addQuoteStep">＋ Ajouter une ligne</button></div><div v-for="(step, index) in quoteForm.steps" :key="index" class="step-line"><span class="step-number">{{ index + 1 }}</span><input v-model="step.startCondition" placeholder="Condition de départ" /><input v-model="step.pinToTest" placeholder="Pin à tester" /><select v-model="step.measurementType"><option>VOLTAGE</option><option>CURRENT</option><option>RESISTANCE</option><option>FREQUENCY</option><option>DUTY_CYCLE</option></select><input v-model="step.expectedMin" type="number" placeholder="Min" /><input v-model="step.expectedMax" type="number" placeholder="Max" /></div></div><div class="modal-actions"><button class="filter-button" @click="showQuoteModal = false">Annuler</button><button class="primary-button" @click="saveQuote">Enregistrer</button></div></div></div>
    <div v-if="showTemplateModal" class="modal-backdrop" @click.self="showTemplateModal = false"><div class="modal template-editor"><div class="modal-heading"><h2>{{ editingTemplate ? 'Modifier le template' : 'Nouveau template' }}</h2><button @click="showTemplateModal = false">×</button></div><p class="modal-help">Variables : {{ templateTokensFull }}.</p><label>Nom<input v-model="templateForm.name" placeholder="GoogleTest hardware" /></label><label>Description<input v-model="templateForm.description" /></label><label>Contenu C++<textarea v-model="templateForm.content" rows="16" spellcheck="false"></textarea></label><div class="modal-actions"><button class="filter-button" @click="showTemplateModal = false">Annuler</button><button class="primary-button" @click="saveTemplate">Enregistrer</button></div></div></div>
    <div v-if="toast" class="toast">✓ {{ toast }}</div>
  </div>
</template>
